import ast, sys, math, operator
sys.setrecursionlimit(10000)
OPS = {ast.Add:operator.add, ast.Sub:operator.sub, ast.Mult:operator.mul,
       ast.Div:operator.truediv, ast.FloorDiv:operator.floordiv,
       ast.Mod:operator.mod, ast.Pow:operator.pow,
       ast.USub:operator.neg, ast.UAdd:operator.pos}
MAX_BITS = 100000
def ck(x):
    if isinstance(x, complex): raise ValueError("complex result not supported")
    if isinstance(x, float) and not math.isfinite(x): raise ValueError("non-finite result")
    if isinstance(x, int) and x.bit_length() > MAX_BITS: raise ValueError("result too large")
    return x
def ev(n):
    if isinstance(n, ast.Expression): return ev(n.body)
    if isinstance(n, ast.Constant):
        if isinstance(n.value, (int, float)) and not isinstance(n.value, bool): return ck(n.value)
        raise ValueError("non-numeric literal")
    if isinstance(n, ast.UnaryOp) and type(n.op) in OPS:
        return ck(OPS[type(n.op)](ev(n.operand)))
    if isinstance(n, ast.BinOp) and type(n.op) in OPS:
        l, r = ev(n.left), ev(n.right)
        if isinstance(n.op, ast.Pow):
            if isinstance(l, int) and isinstance(r, int) and r > 0 and l not in (0,1,-1) and r*l.bit_length() > MAX_BITS:
                raise ValueError("result too large")
        return ck(OPS[type(n.op)](l, r))
    raise ValueError(f"disallowed: {type(n).__name__}")
src = sys.stdin.read().replace("^", "**").replace(",", "")
try:
    result = ev(ast.parse(src, mode="eval"))
    out = f"[arithmetic-eval] {src.strip()} -> {result}"
except (ValueError, SyntaxError, TypeError, ZeroDivisionError, OverflowError, RecursionError, MemoryError) as e:
    print(f"[arithmetic-eval] REJECTED — {e}"); sys.exit(1)
print(out)
